/* ---------- charts ---------- */
const Q = ["Q1 '25", "Q2 '25", "Q3 '25", "Q4 '25", "Q1 '26", "Q2 '26", "Q3 '26", "Q4 '26"];
function lineChart({ w = 640, h = 220, series = [], band, marks = [], yLabels = true }) {
  const L = yLabels ? 34 : 6, R = 10, T = 8, B = 26, iw = w - L - R, ih = h - T - B;
  const X = i => L + i * iw / (Q.length - 1), Y = v => T + ih - v / 100 * ih;
  const path = vals => vals.map((v, i) => `${i ? 'L' : 'M'}${X(i).toFixed(1)} ${Y(v).toFixed(1)}`).join('');
  let s = `<svg viewBox="0 0 ${w} ${h}" width="100%" role="img" aria-label="Compliance strength over eight quarters" style="display:block;overflow:visible">`;
  [0, 25, 50, 75, 100].forEach(v => { s += `<line x1="${L}" x2="${w - R}" y1="${Y(v)}" y2="${Y(v)}" stroke="#e1e2e6" ${v ? 'stroke-dasharray="3 4"' : ''}/>`; if (yLabels) s += `<text x="${L - 10}" y="${Y(v) + 4}" text-anchor="end" font-size="12" fill="#6b6f81">${v}</text>`; });
  Q.forEach((q, i) => { s += `<text x="${X(i)}" y="${h - 6}" text-anchor="middle" font-size="12" fill="#6b6f81">${q}</text>`; });
  marks.forEach(m => { s += `<line x1="${X(m.i)}" x2="${X(m.i)}" y1="${T}" y2="${T + ih}" stroke="#b8bac4"/><rect x="${X(m.i) - m.w / 2}" y="${Y(m.y) - 11}" width="${m.w}" height="22" rx="6" fill="#fff" stroke="#e1e2e6"/><text x="${X(m.i)}" y="${Y(m.y) + 4}" text-anchor="middle" font-size="12" font-weight="500" fill="${m.tone === 'bad' ? '#b42318' : '#1e7a46'}">${m.label}</text>`; });
  if (band) s += `<path d="${path(band[1])}${band[0].slice().reverse().map((v, j) => `L${X(Q.length - 1 - j).toFixed(1)} ${Y(v).toFixed(1)}`).join('')}Z" fill="#c7d2fe" opacity=".55"/>`;
  series.forEach(se => { s += `<path d="${path(se.vals)}" fill="none" stroke="${se.col}" stroke-width="2.2" stroke-linejoin="round"/>`; const last = se.vals.length - 1; s += `<circle cx="${X(last)}" cy="${Y(se.vals[last])}" r="4.5" fill="#fff" stroke="${se.col}" stroke-width="2"/>`; });
  return s + '</svg>';
}
const AVG = [58, 60, 61, 63, 66, 68, 72, 78], LO = [52, 53, 55, 57, 59, 61, 65, 72], HI = [65, 67, 68, 70, 72, 74, 79, 84];
function spark(vals, col, end) { const w = 90, h = 26, mn = Math.min(...vals), mx = Math.max(...vals); const p = vals.map((v, i) => `${i ? 'L' : 'M'}${(i * w / (vals.length - 1)).toFixed(1)} ${(h - 3 - (v - mn) / (mx - mn || 1) * (h - 6)).toFixed(1)}`).join(''); const lx = w, ly = h - 3 - (vals[vals.length - 1] - mn) / (mx - mn || 1) * (h - 6); return `<svg viewBox="0 0 ${w + 4} ${h}" width="${w + 4}" height="${h}" aria-hidden="true"><path d="${p}" fill="none" stroke="${col}" stroke-width="1.6"/><circle cx="${lx}" cy="${ly}" r="2.6" fill="${end}"/></svg>`; }

/* ---------- mini dashboard (replica of Figma "Regulator · Dashboard", used as theme thumbnails) ---------- */
